class Solution:
    def maxOutput(self, n, edges, price):
        from collections import defaultdict
        g = defaultdict(list)
        for a, b in edges:
            g[a].append(b); g[b].append(a)
        def dfs(u, p):
            best = price[u]
            for v in g[u]:
                if v != p:
                    best = max(best, price[u] + dfs(v, u))
            return best
        return max(dfs(r, -1) - price[r] for r in range(n))

