class Solution:
    def maxOutput(self, n, edges, price):
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b); g[b].append(a)
        parent = [-1] * n
        order = []
        stack = [0]
        while stack:
            u = stack.pop()
            order.append(u)
            for v in g[u]:
                if v != parent[u]:
                    parent[v] = u
                    stack.append(v)
        down = price[:]
        for u in reversed(order):
            p = parent[u]
            if p >= 0:
                down[p] = max(down[p], price[p] + down[u])
        return max(d - price[i] for i, d in enumerate(down))

