class Solution {
    public long maxOutput(int n, int[][] edges, int[] price) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) { g.get(e[0]).add(e[1]); g.get(e[1]).add(e[0]); }
        int[] parent = new int[n]; Arrays.fill(parent, -1);
        List<Integer> order = new ArrayList<>();
        Deque<Integer> st = new ArrayDeque<>(); st.push(0);
        while (!st.isEmpty()) {
            int u = st.pop(); order.add(u);
            for (int v : g.get(u)) if (v != parent[u]) { parent[v] = u; st.push(v); }
        }
        long[] down = new long[n];
        for (int i = 0; i < n; i++) down[i] = price[i];
        long ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i), p = parent[u];
            if (p >= 0) down[p] = Math.max(down[p], (long) price[p] + down[u]);
            ans = Math.max(ans, down[u] - price[u]);
        }
        return ans;
    }
}

